/**
 * Shared HTTP route helpers for in-house DSH host plugins.
 *
 * Provides:
 *   - `readBoundedBody`: bounded byte cap, hard timeout (`.unref()`ed),
 *     abort/disconnect handling, and safe `Promise.race` cleanup (no
 *     UnhandledPromiseRejection when timeout wins).
 *   - `sendJson`: consistent UTF-8 JSON responses with proper `HEAD` empty-body
 *     handling and `writableEnded`/`destroyed` guards.
 *   - `isLoopbackAddress`: standard IPv4/IPv6 loopback check.
 *
 * THIS FILE IS THE SOURCE OF TRUTH. Copies in plugins are generated by
 * `tools/sync-shared-code.mjs` and must stay byte-identical.
 *
 * ASCII only: see the workspace AGENTS.md encoding rule.
 */

import { Buffer } from 'node:buffer'

/**
 * Whether a socket remoteAddress is local loopback (127.0.0.1, ::1, ::ffff:127.0.0.1).
 * @param {string|undefined|null} address
 * @returns {boolean}
 */
export function isLoopbackAddress(address) {
  if (typeof address !== 'string') return false
  const trimmed = address.trim().toLowerCase()
  return trimmed === '127.0.0.1' || trimmed === '::1' || trimmed === '::ffff:127.0.0.1'
}

/**
 * Send a JSON response safely, suppressing the body for HEAD requests and
 * avoiding writes to already-ended/destroyed responses.
 *
 * @param {import('node:http').ServerResponse} res
 * @param {number} status
 * @param {unknown} payload
 * @param {{method?: string, headers?: Record<string, string>}} [options]
 */
export function sendJson(res, status, payload, options = {}) {
  if (!res || res.writableEnded || res.destroyed) return
  const body = JSON.stringify(payload)
  const headers = {
    'content-type': 'application/json; charset=utf-8',
    'cache-control': 'no-store',
    'content-length': String(Buffer.byteLength(body, 'utf8')),
    ...(options.headers ?? {}),
  }
  res.writeHead(status, headers)
  if (String(options.method ?? '').toUpperCase() === 'HEAD') {
    res.end()
  } else {
    res.end(body)
  }
}

/**
 * Read a Node IncomingMessage or Fetch Request body with strict byte and time
 * bounds. Throws an Error with `.status` (413 payload too large, 408 timeout,
 * 499 aborted).
 *
 * @param {AsyncIterable<Buffer|Uint8Array|string> & {body?: ReadableStream|null, aborted?: boolean}} req
 * @param {{maxBytes?: number, timeoutMs?: number, signal?: AbortSignal}} [options]
 * @returns {Promise<string>}
 */
export async function readBoundedBody(req, options = {}) {
  const maxBytes = options.maxBytes ?? 64 * 1024
  const timeoutMs = options.timeoutMs ?? 10000
  const signal = options.signal

  if (req?.aborted || signal?.aborted) {
    const error = new Error('request aborted')
    error.status = 499
    throw error
  }

  let timer
  let onAbort
  let cancelRead = () => {}

  const reading = (async () => {
    const chunks = []
    let total = 0

    // Fetch Request / Web ReadableStream path
    if (req && typeof req.body?.getReader === 'function') {
      const reader = req.body.getReader()
      cancelRead = () => { reader.cancel().catch(() => {}) }
      try {
        while (true) {
          const { done, value } = await reader.read()
          if (done) break
          const chunk = Buffer.from(value)
          total += chunk.length
          if (total > maxBytes) {
            const error = new Error('request body too large')
            error.status = 413
            throw error
          }
          chunks.push(chunk)
        }
      } finally {
        try { reader.releaseLock() } catch { /* ignore */ }
      }
      return Buffer.concat(chunks, total).toString('utf8')
    }

    // Node IncomingMessage / AsyncIterable path
    const iterator = req[Symbol.asyncIterator]()
    cancelRead = () => {
      if (typeof iterator.return === 'function') {
        Promise.resolve().then(() => iterator.return()).catch(() => {})
      }
      if (typeof req.destroy === 'function') {
        try { req.destroy() } catch { /* ignore */ }
      }
    }
    while (true) {
      const { done, value } = await iterator.next()
      if (done) break
      const chunk = Buffer.isBuffer(value) ? value : Buffer.from(value)
      total += chunk.length
      if (total > maxBytes) {
        const error = new Error('request body too large')
        error.status = 413
        throw error
      }
      chunks.push(chunk)
    }
    return Buffer.concat(chunks, total).toString('utf8')
  })()

  // Prevent UnhandledPromiseRejection if the timeout/abort branch wins the race.
  reading.catch(() => {})

  const raced = new Promise((_, reject) => {
    if (timeoutMs > 0) {
      timer = setTimeout(() => {
        cancelRead()
        const error = new Error('request body timed out')
        error.status = 408
        reject(error)
      }, timeoutMs)
      if (typeof timer.unref === 'function') timer.unref()
    }
    if (signal) {
      onAbort = () => {
        cancelRead()
        const error = new Error('request aborted')
        error.status = 499
        reject(error)
      }
      signal.addEventListener('abort', onAbort, { once: true })
    }
  })

  try {
    return await Promise.race([reading, raced])
  } finally {
    if (timer !== undefined) clearTimeout(timer)
    if (signal && onAbort) signal.removeEventListener('abort', onAbort)
  }
}

/**
 * Read and JSON.parse a bounded request body. Empty body returns `{}`.
 * Throws an Error with `.status = 400` on invalid JSON.
 *
 * @param {any} req
 * @param {{maxBytes?: number, timeoutMs?: number, signal?: AbortSignal}} [options]
 * @returns {Promise<any>}
 */
export async function readBoundedJson(req, options = {}) {
  const raw = await readBoundedBody(req, options)
  if (raw.trim() === '') return {}
  try {
    return JSON.parse(raw)
  } catch {
    const error = new Error('invalid JSON body')
    error.status = 400
    throw error
  }
}
